WITH valid_order_items AS (SELECT * FROM order_items WHERE quantity <= 6), order_items_stats AS (SELECT CASE WHEN unit_price >= 370 THEN 'high' WHEN unit_price >= 190 THEN 'mid' ELSE 'low' END AS unit_price_bucket, COUNT(*) AS order_item_count, SUM(unit_price) AS total_unit_price FROM valid_order_items GROUP BY CASE WHEN unit_price >= 370 THEN 'high' WHEN unit_price >= 190 THEN 'mid' ELSE 'low' END) SELECT * FROM order_items_stats WHERE total_unit_price >= 1500;
